-- V2 P1-03 知识沉淀：资料、错题、笔记/专栏、合集与 Wiki
CREATE TABLE IF NOT EXISTS resources (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, uploader_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, subject VARCHAR(40) NOT NULL DEFAULT '', grade VARCHAR(40) NOT NULL DEFAULT '', textbook VARCHAR(80) NOT NULL DEFAULT '', exam VARCHAR(80) NOT NULL DEFAULT '', tags VARCHAR(500) NOT NULL DEFAULT '', source VARCHAR(255) NOT NULL DEFAULT '', copyright_note VARCHAR(500) NOT NULL DEFAULT '', download_points INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'pending', download_count INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,created_at), INDEX(subject,grade), INDEX(uploader_id)
);
CREATE TABLE IF NOT EXISTS resource_files (id BIGINT PRIMARY KEY AUTO_INCREMENT, resource_id BIGINT NOT NULL, file_name VARCHAR(255) NOT NULL, file_path VARCHAR(255) NOT NULL, mime_type VARCHAR(120) NOT NULL DEFAULT '', size_bytes BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(resource_id));
CREATE TABLE IF NOT EXISTS resource_downloads (id BIGINT PRIMARY KEY AUTO_INCREMENT, resource_id BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(resource_id,created_at), INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS resource_favorites (resource_id BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(resource_id,user_id));
CREATE TABLE IF NOT EXISTS resource_votes (resource_id BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(resource_id,user_id));
CREATE TABLE IF NOT EXISTS resource_comments (id BIGINT PRIMARY KEY AUTO_INCREMENT, resource_id BIGINT NOT NULL, user_id BIGINT NOT NULL, content VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(resource_id,created_at));
CREATE TABLE IF NOT EXISTS mistakes (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, subject VARCHAR(40) NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, reason TEXT NOT NULL, knowledge_point VARCHAR(120) NOT NULL DEFAULT '', source VARCHAR(255) NOT NULL DEFAULT '', image_path VARCHAR(255), tags VARCHAR(500) NOT NULL DEFAULT '', visibility VARCHAR(20) NOT NULL DEFAULT 'private', error_count INT NOT NULL DEFAULT 1, correct_count INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id,created_at), INDEX(subject,knowledge_point));
CREATE TABLE IF NOT EXISTS mistake_reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, mistake_id BIGINT NOT NULL, user_id BIGINT NOT NULL, result VARCHAR(20) NOT NULL, reviewed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(mistake_id,reviewed_at));
CREATE TABLE IF NOT EXISTS notes (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, subject VARCHAR(40) NOT NULL DEFAULT '', tags VARCHAR(500) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id,updated_at), INDEX(status,updated_at));
CREATE TABLE IF NOT EXISTS note_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, note_id BIGINT NOT NULL, user_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(note_id,created_at));
CREATE TABLE IF NOT EXISTS collections (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL DEFAULT '', cover_url VARCHAR(255), item_count INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', is_featured BOOLEAN NOT NULL DEFAULT FALSE, follower_count INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,is_featured,created_at));
CREATE TABLE IF NOT EXISTS collection_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, collection_id BIGINT NOT NULL, item_type VARCHAR(20) NOT NULL, item_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(collection_id,item_type,item_id), INDEX(collection_id,sort_order));
CREATE TABLE IF NOT EXISTS collection_follows (collection_id BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(collection_id,user_id));
CREATE TABLE IF NOT EXISTS columns (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL DEFAULT '', cover_url VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(owner_id,status));
CREATE TABLE IF NOT EXISTS column_episodes (id BIGINT PRIMARY KEY AUTO_INCREMENT, column_id BIGINT NOT NULL, note_id BIGINT, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, episode_no INT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'published', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(column_id,episode_no), INDEX(column_id,created_at));
CREATE TABLE IF NOT EXISTS wiki_pages (id BIGINT PRIMARY KEY AUTO_INCREMENT, board_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', updated_by BIGINT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(board_id,title), INDEX(board_id,status));
CREATE TABLE IF NOT EXISTS wiki_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, page_id BIGINT NOT NULL, editor_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(page_id,created_at));

ALTER TABLE mistakes ADD COLUMN group_id BIGINT NULL, ADD COLUMN post_id BIGINT NULL, ADD COLUMN next_review_date DATE NULL, ADD INDEX(group_id,visibility);
CREATE TABLE IF NOT EXISTS collection_favorites (collection_id BIGINT NOT NULL,user_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(collection_id,user_id));
CREATE TABLE IF NOT EXISTS resource_uploads (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,file_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT NOT NULL,resource_id BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,resource_id));
